import sys

def lcs_len(a: str, b: str) -> int:
    if not a or not b:
        return 0
    if len(a) > len(b):
        a, b = b, a
    m = len(a)
    if m == len(b) and a == b:
        return m
    pos = {}
    for i, ch in enumerate(a):
        pos[ch] = pos.get(ch, 0) | (1 << i)

    S = (1 << m) - 1
    mask = S
    for ch in b:
        pm = pos.get(ch, 0)
        if pm:
            u = S & pm
            S = (S + u) | (S - u)
    return m - (S & mask).bit_count()

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        a = lines[0] if len(lines) >= 1 else ""
        b = ""
    else:
        a, b = lines[0], lines[1]
    print(lcs_len(a, b))

if __name__ == '__main__':
    main()
